<script setup>
import { computed, nextTick, ref, watch } from 'vue'
const text = ref(localStorage.getItem('mayek-draft') || '')
const editor = ref(null), light = ref(false), notice = ref(''), expanded = ref(false)
const script = ref(localStorage.getItem('keyboard-script') || 'mayek')
const page = ref('studio')
const sourceText = ref(''), dictionaryWord = ref(''), dictionaryResult = ref('')
const dictionaryOnly = ref(localStorage.getItem('mayek-dictionary-only')==='true')
const dictionaryPage = ref(1), dictionaryPageSize = 100
const starterDictionary = [
  {source:'প্রেম্‌',target:'ꯄ꯭ꯔꯦꯝ'}, {source:'নুংশিব',target:'ꯅꯨꯡꯁꯤꯕ'},
  {source:'প্রেমী',target:'ꯄ꯭ꯔꯦꯃꯤ'}, {source:'অমসুং',target:'ꯑꯃꯁꯨꯡ'},
  {source:'পাত্র',target:'ꯄꯥꯇ꯭ꯔ'}, {source:'প্রিয়',target:'ꯄ꯭ꯔꯤꯌ'},
  {source:'অসি',target:'ꯑꯁꯤ'}, {source:'অহুম্‌',target:'ꯑꯍꯨꯝ'},
  {source:'থোক্তুনসু',target:'ꯊꯣꯛꯇꯨꯟꯁꯨ'}, {source:'অমখক্ত',target:'ꯑꯃꯈꯛꯇ'},
  {source:'ওইন',target:'ꯑꯣꯏꯟ'}, {source:'খঙ্‌নব',target:'ꯈꯡ‌ꯅꯕ'},
  {source:'খঙ্‌ঙম্‌দব',target:'ꯈꯡ‌ꯉꯝ‌ꯗꯕ'}, {source:'অহুম্‌গী',target:'ꯑꯍꯨꯝ‌ꯒꯤ'},
  {source:'অমত্ত',target:'ꯑꯃꯠꯇ'}, {source:'ওইব',target:'ꯑꯣꯏꯕ'},
  {source:'শক্তম্বু',target:'ꯁꯛꯇꯝꯕꯨ'}, {source:'ঐন',target:'ꯑꯩꯅ'},
  {source:'প্রণাম্‌',target:'ꯄ꯭ꯔꯅꯥꯝ'}, {source:'তৌজরি',target:'ꯇꯧꯖꯔꯤ'}
]
const transliterationDictionary = ref((()=>{let saved=[];try{saved=JSON.parse(localStorage.getItem('mayek-transliteration-dictionary')||'[]')}catch{}if(localStorage.getItem('mayek-starter-dictionary-v1'))return saved;const merged=new Map(starterDictionary.map(entry=>[entry.source,entry]));for(const entry of saved)merged.set(entry.source,entry);const result=[...merged.values()];localStorage.setItem('mayek-starter-dictionary-v1','1');localStorage.setItem('mayek-transliteration-dictionary',JSON.stringify(result));return result})())
const lastRomanKey = ref(''), lastRomanTime = ref(0)
const bengaliPending = ref('')
let bengaliTimer
const consonants = [['k','ꯀ'],['s','ꯁ'],['l','ꯂ'],['m','ꯃ'],['p','ꯄ'],['n','ꯅ'],['c','ꯆ'],['t','ꯇ'],['K','ꯈ'],['N','ꯉ'],['T','ꯊ'],['w','ꯋ'],['y','ꯌ'],['h','ꯍ'],['U','ꯎ'],['I','ꯏ'],['f','ꯐ'],['A','ꯑ'],['g','ꯒ'],['J','ꯓ'],['r','ꯔ'],['b','ꯕ'],['j','ꯖ'],['d','ꯗ'],['G','ꯘ'],['D','ꯙ'],['B','ꯚ']]
const finalConsonants = [['k\'','ꯛ'],['l\'','ꯜ'],['m\'','ꯝ'],['p\'','ꯞ'],['n\'','ꯟ'],['t\'','ꯠ'],['N\'','ꯡ'],['I\'','ꯢ']]
const vowels = [['o','ꯣ'],['i','ꯤ'],['a','ꯥ'],['e','ꯦ'],['ou','ꯧ'],['u','ꯨ'],['ei','ꯩ']]
const signs = ['ꯪ','꯫','꯬','꯭'], digits = [...'0123456789'].map((n,i)=>[n,String.fromCodePoint(0xABF0+i)])
const bengaliVowels = [['o','অ'],['a','আ'],['i','ই'],['I','ঈ'],['u','উ'],['U','ঊ'],['rri','ঋ'],['e','এ'],['OI','ঐ'],['O','ও'],['OU','ঔ']]
const bengaliConsonants = [['k','ক'],['kh','খ'],['g','গ'],['gh','ঘ'],['Ng','ঙ'],['c','চ'],['ch','ছ'],['j','জ'],['jh','ঝ'],['NG','ঞ'],['T','ট'],['Th','ঠ'],['D','ড'],['Dh','ঢ'],['N','ণ'],['t','ত'],['th','থ'],['d','দ'],['dh','ধ'],['n','ন'],['p','প'],['ph','ফ'],['b','ব'],['bh','ভ'],['m','ম'],['z','য'],['r','র'],['l','ল'],['sh','শ'],['Sh','ষ'],['s','স'],['h','হ'],['R','ড়'],['Rh','ঢ়'],['y','য়'],['Y','য']]
const bengaliSigns = [...'ািীুূৃেৈোৌংঃঁ']
const bengaliSignKeys = ['a','i','I','u','U','rri','e','OI','O','OU','ng',':','~']
const bengaliExtra = ['ৠ','ৰ','ৱ','ৎ','ং','ঃ','ঁ','ৗ','়','্','‍','‌','৲','৳','৴','৵','৶','৷','৹','।','॥','ঽ','৺']
const avroRules = {k:'ক',kh:'খ',g:'গ',gh:'ঘ',Ng:'ঙ',c:'চ',ch:'ছ',j:'জ',jh:'ঝ',NG:'ঞ',T:'ট',Th:'ঠ',D:'ড',Dh:'ঢ',N:'ণ',t:'ত',th:'থ',d:'দ',dh:'ধ',n:'ন',p:'প',ph:'ফ',b:'ব',bh:'ভ',m:'ম',z:'য',r:'র',l:'ল',sh:'শ',Sh:'ষ',s:'স',h:'হ',R:'ড়',Rh:'ঢ়',y:'য়',Y:'য',o:'অ',a:'আ',A:'আ',i:'ই',I:'ঈ',u:'উ',U:'ঊ',rri:'ঋ',e:'এ',OI:'ঐ',O:'ও',OU:'ঔ',ng:'ং',':':'ঃ','~':'ঁ',w:'ও',v:'ভ',f:'ফ',q:'ক',x:'ক্স'}
const bengaliDigits = [...'0123456789'].map((n,i)=>[n,String.fromCodePoint(0x09E6+i)])
const conjuncts = 'ক্ষ ঙ্ক ঙ্গ জ্ঞ ঞ্চ ঞ্ছ ঞ্জ ত্ত ষ্ণ হ্ম ণ্ড ক্র ক্ত স্ত্র ত্র দ্র দ্ব দ্ধ ন্ত ন্দ ন্ধ স্থ শ্চ শ্র ষ্ট ষ্ঠ স্ক স্প স্ব স্ম ক্ল গ্ন গ্ম চ্ছ জ্জ'.split(' ')
const isBengali = computed(()=>script.value==='bengali')
const activeConsonants = computed(()=>isBengali.value?bengaliConsonants:consonants)
const activeVowels = computed(()=>isBengali.value?bengaliVowels:vowels)
const activeSigns = computed(()=>isBengali.value?bengaliSigns:signs)
const activeDigits = computed(()=>isBengali.value?bengaliDigits:digits)
const count = computed(()=>[...text.value].length)
const dictionaryPageCount = computed(()=>Math.max(1,Math.ceil(transliterationDictionary.value.length/dictionaryPageSize)))
const paginatedDictionary = computed(()=>{const page=Math.min(dictionaryPage.value,dictionaryPageCount.value);return transliterationDictionary.value.slice((page-1)*dictionaryPageSize,page*dictionaryPageSize)})
const bengaliToMayek = {'ক':'ꯀ','খ':'ꯈ','গ':'ꯒ','ঘ':'ꯘ','ঙ':'ꯉ','চ':'ꯆ','ছ':'ꯕ','জ':'ꯖ','ঝ':'ꯓ','ঞ':'ꯅ','ট':'ꯇ','ঠ':'ꯊ','ড':'ꯗ','ঢ':'ꯙ','ণ':'ꯅ','ত':'ꯇ','থ':'ꯊ','দ':'ꯗ','ধ':'ꯙ','ন':'ꯅ','প':'ꯄ','ফ':'ꯐ','ব':'ꯕ','ভ':'ꯚ','ম':'ꯃ','য':'ꯌ','র':'ꯔ','ল':'ꯂ','শ':'ꯁ','ষ':'ꯁ','স':'ꯁ','হ':'ꯍ','ড়':'ꯔ','ঢ়':'ꯔ','য়':'ꯏ','ৰ':'ꯔ','ৱ':'ꯋ','অ':'ꯑ','আ':'ꯑꯥ','ই':'ꯏ','ঈ':'ꯏ','উ':'ꯎ','ঊ':'ꯎ','ঋ':'ꯔ','এ':'ꯑꯦ','ঐ':'ꯑꯩ','ও':'ꯑꯣ','ঔ':'ꯑꯧ','া':'ꯥ','ি':'ꯤ','ী':'ꯤ','ু':'ꯨ','ূ':'ꯨ','ৃ':'ꯔ','ে':'ꯦ','ৈ':'ꯩ','ো':'ꯣ','ৌ':'ꯧ','ং':'ꯪ','ঃ':'꯫','ঁ':'꯬'}
const transliteratedText = computed(()=>{const input=sourceText.value,entries=[...transliterationDictionary.value].filter(e=>e.source&&e.target).sort((a,b)=>b.source.length-a.source.length),out=[];let i=0;while(i<input.length){const left=input[i-1]||'',match=entries.find(e=>input.startsWith(e.source,i)&&!/[\u0980-\u09ff]/.test(left)&&!/[\u0980-\u09ff]/.test(input[i+e.source.length]||''));if(match){out.push(match.target);i+=match.source.length;continue}const char=String.fromCodePoint(input.codePointAt(i));i+=char.length;if(dictionaryOnly.value){out.push(char);continue}if(char==='\u200c'||char==='\u200d'||char==='্')continue;out.push(bengaliToMayek[char]??char)}return out.join('')})
watch(text,v=>localStorage.setItem('mayek-draft',v))
watch(transliterationDictionary,v=>localStorage.setItem('mayek-transliteration-dictionary',JSON.stringify(v)),{deep:true})
watch(()=>transliterationDictionary.value.length,()=>{dictionaryPage.value=Math.min(dictionaryPage.value,dictionaryPageCount.value)})
watch(dictionaryOnly,v=>localStorage.setItem('mayek-dictionary-only',String(v)))
function addDictionaryEntry(){const source=dictionaryWord.value.trim(),target=dictionaryResult.value.trim();if(!source||!target)return;transliterationDictionary.value=transliterationDictionary.value.filter(e=>e.source!==source);transliterationDictionary.value.unshift({source,target});dictionaryPage.value=1;dictionaryWord.value='';dictionaryResult.value=''}
function exportDictionary(){const blob=new Blob([JSON.stringify(transliterationDictionary.value,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='meetei-mayek-dictionary.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);ping('Dictionary exported')}
function insert(g){const el=editor.value;if(!el){text.value+=g;return}const a=el.selectionStart,b=el.selectionEnd;const isVowelSign=isBengali.value?bengaliSigns.slice(0,10).includes(g):vowels.some(([,sign])=>sign===g);const previous=[...text.value.slice(0,a)].at(-1);if(isVowelSign&&(!previous||/\s/.test(previous))){ping('Add a consonant first, then choose a vowel sign');el.focus();return}text.value=text.value.slice(0,a)+g+text.value.slice(b);nextTick(()=>{el.focus();el.setSelectionRange(a+g.length,a+g.length)})}
function insertBengaliRoman(key){const el=editor.value,caret=el?.selectionStart??text.value.length,end=el?.selectionEnd??caret;const at=text.value.slice(0,caret),last=[...at].at(-1);const vowels={a:['আ','া'],A:['আ','া'],o:['অ','ো'],O:['ও','ো'],i:['ই','ি'],I:['ঈ','ী'],u:['উ','ু'],U:['ঊ','ূ'],e:['এ','ে'],OI:['ঐ','ৈ'],OU:['ঔ','ৌ'],rri:['ঋ','ৃ']};let glyph=avroRules[key];if(vowels[key])glyph=/[\u0995-\u09B9\u09DC-\u09DF]/u.test(last||'')?vowels[key][1]:vowels[key][0];else if(/[\u0995-\u09B9\u09DC-\u09DF]/u.test(last||'')&&last!=='্')glyph='্'+glyph;if(glyph){text.value=at+glyph+text.value.slice(end);nextTick(()=>{el?.focus();el?.setSelectionRange(caret+glyph.length,caret+glyph.length)})}}
function flushAvro(force=false){clearTimeout(bengaliTimer);let rest=bengaliPending.value;bengaliPending.value='';while(rest){let match='';for(let i=1;i<=rest.length;i++){if(avroRules[rest.slice(0,i)])match=rest.slice(0,i)}if(match&&(!Object.keys(avroRules).some(k=>k.startsWith(rest)&&k.length>rest.length)||force)){insertBengaliRoman(match);rest=rest.slice(match.length);continue}if(match&&!force){bengaliPending.value=rest;break}if(!match){if(!force&&Object.keys(avroRules).some(k=>k.startsWith(rest))) {bengaliPending.value=rest;break}insert(rest[0]);rest=rest.slice(1);continue}insertBengaliRoman(match);rest=rest.slice(match.length)}}
function keydown(e){if(isBengali.value){if(e.ctrlKey||e.metaKey||e.altKey)return;if(/^[a-zA-Z]$/.test(e.key)){e.preventDefault();bengaliPending.value+=e.key;flushAvro();bengaliTimer=setTimeout(()=>flushAvro(true),450);return}if(/^\d$/.test(e.key)){flushAvro(true);e.preventDefault();insert(String.fromCodePoint(0x09E6+Number(e.key)));return}flushAvro(true);return}if(e.ctrlKey||e.metaKey||e.altKey||e.key.length!==1){lastRomanKey.value='';return}const el=editor.value;const caret=el?.selectionStart??text.value.length;if(e.key==="'"){const finals={k:'ꯛ',l:'ꯜ',m:'ꯝ',p:'ꯞ',n:'ꯟ',t:'ꯠ',N:'ꯡ',I:'ꯢ'},base=consonants.find(([key])=>key===lastRomanKey.value)?.[1],glyph=finals[lastRomanKey.value];if(glyph&&base&&text.value.slice(0,caret).endsWith(base)){e.preventDefault();const start=caret-base.length;text.value=text.value.slice(0,start)+glyph+text.value.slice(caret);lastRomanKey.value='';nextTick(()=>{el?.focus();el?.setSelectionRange(start+glyph.length,start+glyph.length)});return}}if(e.key==='M'){e.preventDefault();insert('ꯪ');lastRomanKey.value='';return}const digraphs={g:{prefix:'n',before:'ꯅ',glyph:'ꯉ'},u:{prefix:'o',before:'ꯣ',glyph:'ꯧ'},i:{prefix:'e',before:'ꯦ',glyph:'ꯩ'}};const pair=digraphs[e.key.toLowerCase()];if(pair&&lastRomanKey.value.toLowerCase()===pair.prefix&&Date.now()-lastRomanTime.value<900&&text.value.slice(0,caret).endsWith(pair.before)){e.preventDefault();const start=caret-1;text.value=text.value.slice(0,start)+pair.glyph+text.value.slice(caret);lastRomanKey.value='';nextTick(()=>{el.focus();el.setSelectionRange(start+1,start+1)});return}const found=[...activeConsonants.value,...activeVowels.value,...activeDigits.value].find(([k])=>k===e.key);if(found){e.preventDefault();insert(found[1]);lastRomanKey.value=e.key;lastRomanTime.value=Date.now()}else lastRomanKey.value=''}
watch(script,v=>{if(bengaliPending.value)flushAvro(true);localStorage.setItem('keyboard-script',v);lastRomanKey.value=''})
function ping(s){notice.value=s;setTimeout(()=>notice.value='',2000)}
async function copy(){try{await navigator.clipboard.writeText(text.value);ping('Copied to clipboard')}catch{editor.value.select();document.execCommand('copy');ping('Copied to clipboard')}}
function save(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text.value],{type:'text/plain;charset=utf-8'}));a.download=isBengali.value?'manipuri-bengali.txt':'meetei-mayek.txt';a.click();URL.revokeObjectURL(a.href);ping('Your text is downloaded')}
function load(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{text.value=String(r.result||'');ping('Document opened')};r.readAsText(f);e.target.value=''}
</script>
<template>
<main class="app" :class="{'day':light,'wide':expanded}">
 <header class="nav"><a class="logo" href="#"><span class="seal">ꯃ</span><span>mayek<span class="dot">.</span><small>WRITING STUDIO</small></span></a><div class="page-tabs" role="tablist" aria-label="Pages"><button role="tab" :aria-selected="page==='studio'" :class="{selected:page==='studio'}" @click="page='studio'">Studio</button><button role="tab" :aria-selected="page==='transliterate'" :class="{selected:page==='transliterate'}" @click="page='transliterate'">Transliterate</button></div><div v-if="page==='studio'" class="compose-head"><div><span class="eyebrow">01 — COMPOSE</span><span class="draft"><i></i> Autosaved</span></div><button class="expand" @click="expanded=!expanded">{{expanded?'↙':'↗'}} {{expanded?'Collapse':'Focus mode'}}</button></div><div class="nav-right"><span class="status"><i></i> YOUR WORKSPACE</span><button class="theme" @click="light=!light"><span>{{light?'☾':'☼'}}</span> {{light?'Night':'Day'}} mode</button></div></header>
 <template v-if="page==='studio'"><section class="compose"><div class="editor"><div class="margin-mark">{{String(count).padStart(2,'0')}}</div><textarea ref="editor" v-model="text" :class="{'bengali-textarea':isBengali}" @keydown="keydown" placeholder="Begin with a thought…" :aria-label="isBengali?'Manipuri Bengali text editor':'Meetei Mayek text editor'" spellcheck="false"></textarea><div class="editor-bottom"><span>Unicode text · Ready to share anywhere</span><span>{{count}} characters</span></div></div></section>
 <section class="keyboard"><div class="key-head"><div class="actions toolbar-actions"><div class="action-left"><button @click="copy"><b>▢</b> Copy text</button><button @click="save"><b>↓</b> Download</button><label class="upload"><b>＋</b> Open file<input type="file" accept=".txt,text/plain" @change="load"></label></div></div><div class="keyboard-title"><span class="eyebrow">02 — CHARACTER BOARD</span><h2>Build your script<span>.</span></h2></div><div class="script-switch" role="group" aria-label="Keyboard script"><button :class="{selected:!isBengali}" @click="script='mayek'">Meetei Mayek</button><button :class="{selected:isBengali}" @click="script='bengali'">Manipuri · বাংলা</button></div><div class="key-note"><span class="key-hint">⌨</span><span>Tap a character<br>to add it above</span></div><button class="clear" @click="text=''">Clear page <span>↗</span></button></div>
  <div class="board" :class="{'bengali-board':isBengali}"><div v-if="isBengali" class="keys vowel-row"><button v-for="([roman,glyph]) in activeVowels" :key="glyph" class="key" @click="insert(glyph)" :aria-label="roman"><span class="roman">{{roman}}</span><span class="glyph">{{glyph}}</span></button></div><div class="row-title"><span>{{isBengali?'ব্যঞ্জনবর্ণ':'CONSONANTS'}}</span><i></i><small>{{isBengali?'Avro phonetic · Manipuri Bengali':'Meetei Mayek letters'}}</small></div><div class="keys consonants" :class="{'bengali-keys':isBengali}"><button v-for="([roman,glyph]) in activeConsonants" :key="glyph" class="key" @click="insert(glyph)" :aria-label="roman+' '+glyph"><span class="roman">{{roman}}</span><span class="glyph">{{glyph}}</span></button></div>
  <div v-if="!isBengali" class="final-group"><div class="row-title"><span>FINAL CONSONANTS</span><i></i><small>Apostrophe after consonant · M = ꯪ</small></div><div class="keys final-keys"><button v-for="([roman,glyph]) in finalConsonants" :key="glyph" class="key" @click="insert(glyph)" :aria-label="roman+' '+glyph"><span class="roman">{{roman}}</span><span class="glyph">{{glyph}}</span></button></div></div>
  <div v-if="isBengali" class="conjunct-group"><div class="row-title"><span>যুক্তাক্ষর</span><i></i><small>Common conjuncts</small></div><div class="keys conjuncts"><button v-for="g in conjuncts" :key="g" class="key" @click="insert(g)"><span class="glyph">{{g}}</span></button></div></div>
  <div class="lower-board"><div class="key-group"><div class="row-title"><span>{{isBengali?'কার চিহ্ন':'VOWELS · SIGNS & HALANT'}}</span><i></i><small>{{isBengali?'Choose a consonant first':'Choose a vowel or sign'}}</small></div><div v-if="isBengali" class="keys vowels"><button v-for="(g,i) in activeSigns" :key="g" class="key" @click="insert(g)"><span class="roman">{{bengaliSignKeys[i]}}</span><span class="glyph">{{g}}</span></button></div><div v-else class="keys mayek-symbols"><button v-for="([roman,glyph]) in [...vowels,...signs.map(g=>[g,g]) ]" :key="glyph" class="key sign" @click="insert(glyph)" :aria-label="glyph==='꯭'?'Halant (Apun Iyek)':roman"><span class="roman">{{glyph==='꯭'?'halant':roman}}</span><span class="glyph">{{glyph}}</span></button></div></div><div class="key-group number-group"><div class="row-title"><span>{{isBengali?'সংখ্যা':'NUMERALS'}}</span><i></i></div><div class="keys numbers"><button v-for="([n,g]) in activeDigits" :key="n" class="key" @click="insert(g)"><span class="roman">{{n}}</span><span class="glyph">{{g}}</span></button></div></div></div>
  <div v-if="isBengali" class="extra-group"><div class="row-title"><span>অতিরিক্ত</span><i></i><small>Extra Characters</small></div><div class="keys extra-characters"><button v-for="g in bengaliExtra" :key="g" class="key" @click="insert(g)" :aria-label="g==='‍'?'Insert zero-width joiner':g==='‌'?'Insert zero-width non-joiner':'Extra character '+g"><span class="glyph">{{g==='‍'?'ZWJ':g==='‌'?'ZWNJ':g}}</span></button><button class="key phala-key" @click="insert('্য')" aria-label="Insert য-ফলা"><span class="glyph">◌্য</span><span class="phala-label">য-ফলা</span></button><button class="key phala-key" @click="insert('্র')" aria-label="Insert র-ফলা"><span class="glyph">◌্র</span><span class="phala-label">র-ফলা</span></button></div></div>
  </div></section><footer><span><b>{{isBengali?'ম':'ꯃ'}}</b> Made with care for {{isBengali?'Manipuri Bengali':'Meetei Mayek'}}</span><span>{{isBengali?'MANIPURI BENGALI':'MEETEI MAYEK'}} · UNICODE</span></footer></template>
 <section v-else class="transliterator"><div class="translit-heading"><span class="eyebrow">BENGALI → MEETEI MAYEK</span><h1>Transliteration studio<span>.</span></h1><p>Type Bengali on the left; the Meetei Mayek result updates as you type.</p></div><div class="translit-panels"><label class="translit-panel"><span>Original · বাংলা</span><textarea v-model="sourceText" placeholder="বাংলা লিখুন…" spellcheck="false"></textarea></label><label class="translit-panel"><span>Transliterated · ꯃꯤꯇꯩ ꯃꯌꯦꯛ</span><textarea :value="transliteratedText" readonly placeholder="ꯃꯌꯦꯛ"></textarea></label></div><section class="dictionary-editor"><div class="dictionary-heading"><div><span class="eyebrow">PERSONAL WORD LIST</span><h2>Dictionary editor <span class="dictionary-count">{{transliterationDictionary.length}} words</span></h2></div><p>Dictionary matches are saved in this browser. Turn on Dictionary only to leave unmatched text unchanged.</p></div><div class="dictionary-tools"><label class="dictionary-toggle"><input type="checkbox" v-model="dictionaryOnly"><span>Dictionary only</span></label><button type="button" class="dictionary-export" @click="exportDictionary">↓ Export JSON</button></div><form class="dictionary-form" @submit.prevent="addDictionaryEntry"><label>Bengali word<input v-model="dictionaryWord" placeholder="হায়‌ব‌দি" autocomplete="off"></label><label>Meetei Mayek result<input v-model="dictionaryResult" placeholder="ꯍꯥꯏꯕꯗꯤ" autocomplete="off"></label><button type="submit">＋ Add word</button></form><div v-if="transliterationDictionary.length" class="dictionary-list"><div v-for="entry in paginatedDictionary" :key="entry.source" class="dictionary-entry"><span>{{entry.source}}</span><b>→</b><span>{{entry.target}}</span><button @click="transliterationDictionary=transliterationDictionary.filter(item=>item.source!==entry.source)" :aria-label="'Remove '+entry.source">×</button></div></div><div v-if="dictionaryPageCount>1" class="dictionary-pagination"><span>Page {{dictionaryPage}} of {{dictionaryPageCount}}</span><div><button type="button" :disabled="dictionaryPage===1" @click="dictionaryPage--">← Previous</button><button type="button" :disabled="dictionaryPage===dictionaryPageCount" @click="dictionaryPage++">Next →</button></div></div><p v-if="!transliterationDictionary.length" class="dictionary-empty">No custom words yet. Add a word pair above.</p></section></section>
 <Transition><div v-if="notice" class="toast">{{notice}}</div></Transition>
</main>
</template>
